import type { ContentPack } from '../types';
import { lesson, M, Nq, TF } from '../lib';

const P: ContentPack = {
  '5P-CM-1': lesson(['La célula es la unidad más pequeña de un ser vivo. Todos los seres vivos están formados por una o muchas células.|La cèl·lula és la unitat més xicoteta d’un ésser viu. Tots els éssers vius estan formats per una o moltes cèl·lules.|The cell is the smallest unit of a living thing. All living things are made of one or many cells.', 'Partes principales: membrana (la envoltura), citoplasma (el interior) y núcleo (el centro de control). Las células vegetales tienen además pared celular y cloroplastos.|Parts principals: membrana (l’embolcall), citoplasma (l’interior) i nucli (el centre de control). Les cèl·lules vegetals tenen a més paret cel·lular i cloroplasts.|Main parts: membrane (the outer layer), cytoplasm (the inside) and nucleus (the control centre). Plant cells also have a cell wall and chloroplasts.'],
    '¿Qué parte de la célula la controla?|Quina part de la cèl·lula la controla?|Which part of the cell controls it?', ['Contiene la información genética.|Conté la informació genètica.|It holds the genetic information.', 'El núcleo.|El nucli.|The nucleus.'], [
    M('¿Con qué instrumento se ven las células?|Amb quin instrument es veuen les cèl·lules?|What do we use to see cells?', 'el microscopio|el microscopi|a microscope', ['el telescopio|el telescopi|a telescope', 'la lupa de bolsillo|la lupa de butxaca|a pocket magnifier'], 'Son demasiado pequeñas para verlas a simple vista.|Són massa xicotetes per a veure-les a simple vista.|They are too small to see with the naked eye.'),
    M('¿Qué tienen las células vegetales que no tienen las animales?|Què tenen les cèl·lules vegetals que no tenen les animals?|What do plant cells have that animal cells do not?', 'pared celular y cloroplastos|paret cel·lular i cloroplasts|a cell wall and chloroplasts', ['núcleo|nucli|a nucleus', 'membrana|membrana|a membrane'], 'Los cloroplastos hacen la fotosíntesis.|Els cloroplasts fan la fotosíntesi.|Chloroplasts carry out photosynthesis.'),
    M('¿Qué parte envuelve la célula y deja pasar sustancias?|Quina part embolcalla la cèl·lula i deixa passar substàncies?|Which part surrounds the cell and lets substances in and out?', 'la membrana|la membrana|the membrane', ['el núcleo|el nucli|the nucleus', 'el cloroplasto|el cloroplast|the chloroplast'], 'Es como la piel de la célula.|És com la pell de la cèl·lula.|It is like the cell’s skin.'),
    TF('Una bacteria está formada por una sola célula.|Un bacteri està format per una sola cèl·lula.|A bacterium is made of a single cell.', true, 'Es un ser unicelular.|És un ésser unicel·lular.|It is a single-celled organism.'),
    M('Un ser vivo formado por muchas células es…|Un ésser viu format per moltes cèl·lules és…|A living thing made of many cells is…', 'pluricelular|pluricel·lular|multicellular', ['unicelular|unicel·lular|single-celled', 'inerte|inert|non-living'], 'Pluri = muchos.|Pluri = molts.|Multi = many.'),
    M('¿Qué parte de la célula vegetal es verde?|Quina part de la cèl·lula vegetal és verda?|Which part of a plant cell is green?', 'los cloroplastos|els cloroplasts|the chloroplasts', ['el núcleo|el nucli|the nucleus', 'la pared|la paret|the wall'], 'Tienen clorofila.|Tenen clorofil·la.|They contain chlorophyll.'),
  ]),
  '5P-CM-2': lesson(['Una cadena alimentaria muestra quién se come a quién: productores (plantas) → consumidores primarios (herbívoros) → consumidores secundarios (carnívoros).|Una cadena alimentària mostra qui es menja qui: productors (plantes) → consumidors primaris (herbívors) → consumidors secundaris (carnívors).|A food chain shows who eats whom: producers (plants) → primary consumers (herbivores) → secondary consumers (carnivores).', 'Los descomponedores (hongos y bacterias) transforman los restos en sales minerales que vuelven al suelo.|Els descomponedors (fongs i bacteris) transformen les restes en sals minerals que tornen al sòl.|Decomposers (fungi and bacteria) turn remains into minerals that go back into the soil.'],
    'Hierba → conejo → zorro. ¿Quién es el productor?|Herba → conill → rabosa. Qui és el productor?|Grass → rabbit → fox. Which is the producer?', ['El productor fabrica su alimento.|El productor fabrica el seu aliment.|The producer makes its own food.', 'La hierba.|L’herba.|The grass.'], [
    M('En «hierba → conejo → zorro», ¿qué es el conejo?|En «herba → conill → rabosa», què és el conill?|In "grass → rabbit → fox", what is the rabbit?', 'consumidor primario (herbívoro)|consumidor primari (herbívor)|primary consumer (herbivore)', ['productor|productor|producer', 'descomponedor|descomponedor|decomposer'], 'Come plantas.|Menja plantes.|It eats plants.'),
    M('¿Qué seres vivos son descomponedores?|Quins éssers vius són descomponedors?|Which living things are decomposers?', 'hongos y bacterias|fongs i bacteris|fungi and bacteria', ['leones|lleons|lions', 'árboles|arbres|trees'], 'Descomponen restos de seres vivos.|Descomponen restes d’éssers vius.|They break down dead remains.'),
    M('¿Con qué empieza siempre una cadena alimentaria?|Amb què comença sempre una cadena alimentària?|What does a food chain always start with?', 'un productor|un productor|a producer', ['un carnívoro|un carnívor|a carnivore', 'un hongo|un fong|a fungus'], 'Las plantas captan la energía del sol.|Les plantes capten l’energia del sol.|Plants capture the sun’s energy.'),
    TF('Si desaparecen los conejos, los zorros pueden pasar hambre.|Si desapareixen els conills, les raboses poden passar fam.|If rabbits disappear, foxes may go hungry.', true, 'Todos los eslabones están conectados.|Totes les baules estan connectades.|All the links are connected.'),
    M('Un animal que come plantas y animales es…|Un animal que menja plantes i animals és…|An animal that eats plants and animals is…', 'omnívoro|omnívor|an omnivore', ['herbívoro|herbívor|a herbivore', 'productor|productor|a producer'], 'Omni = todo.|Omni = tot.|Omni = all.'),
    M('Algas → pez pequeño → atún. ¿Qué es el atún?|Algues → peix xicotet → tonyina. Què és la tonyina?|Algae → small fish → tuna. What is the tuna?', 'consumidor secundario|consumidor secundari|secondary consumer', ['productor|productor|producer', 'consumidor primario|consumidor primari|primary consumer'], 'Se come a otro consumidor.|Es menja un altre consumidor.|It eats another consumer.'),
  ]),
  '5P-CM-3': lesson(['Un ecosistema está en equilibrio cuando sus poblaciones se mantienen estables. Factores bióticos (seres vivos) y abióticos (agua, luz, temperatura, suelo) se influyen mutuamente.|Un ecosistema està en equilibri quan les seues poblacions es mantenen estables. Factors biòtics (éssers vius) i abiòtics (aigua, llum, temperatura, sòl) s’influïxen mútuament.|An ecosystem is in balance when its populations stay stable. Biotic factors (living things) and abiotic factors (water, light, temperature, soil) affect each other.', 'Las especies invasoras, la contaminación o la caza excesiva rompen ese equilibrio.|Les espècies invasores, la contaminació o la caça excessiva trenquen eixe equilibri.|Invasive species, pollution and overhunting upset that balance.'],
    'Si en un lago se introduce un pez que se come a los peces autóctonos, ¿qué pasa?|Si en un llac s’introduïx un peix que es menja els peixos autòctons, què passa?|If a fish that eats native fish is introduced into a lake, what happens?', ['Es una especie invasora.|És una espècie invasora.|It is an invasive species.', 'Los peces autóctonos disminuyen y se rompe el equilibrio.|Els peixos autòctons disminuïxen i es trenca l’equilibri.|Native fish decline and the balance is broken.'], [
    M('¿Qué es una especie invasora?|Què és una espècie invasora?|What is an invasive species?', 'Una especie traída de fuera que perjudica a las de aquí|Una espècie portada de fora que perjudica les d’ací|A species brought from elsewhere that harms local ones', ['Una especie que vive aquí desde siempre|Una espècie que viu ací des de sempre|A species that has always lived here', 'Una planta pequeña|Una planta xicoteta|A small plant'], 'Compite con las autóctonas.|Competix amb les autòctones.|It competes with native species.'),
    M('¿Cuál es un factor abiótico de L’Albufera?|Quin és un factor abiòtic de l’Albufera?|Which is an abiotic factor at L’Albufera?', 'la temperatura del agua|la temperatura de l’aigua|water temperature', ['los patos|els ànecs|ducks', 'los juncos|els joncs|reeds'], 'No es un ser vivo.|No és un ésser viu.|It is not alive.'),
    TF('La contaminación del agua puede romper el equilibrio de un río.|La contaminació de l’aigua pot trencar l’equilibri d’un riu.|Water pollution can upset a river’s balance.', true, 'Afecta a peces, plantas e insectos.|Afecta peixos, plantes i insectes.|It affects fish, plants and insects.'),
    M('Si desaparecen los depredadores de los ratones, ¿qué ocurre?|Si desapareixen els depredadors dels ratolins, què passa?|If mice lose their predators, what happens?', 'Hay demasiados ratones|Hi ha massa ratolins|There are too many mice', ['No cambia nada|No canvia res|Nothing changes', 'Desaparecen los ratones|Desapareixen els ratolins|The mice disappear'], 'Nadie controla su población.|Ningú controla la seua població.|Nothing controls their numbers.'),
    M('¿Qué ayuda a mantener el equilibrio de un ecosistema?|Què ajuda a mantindre l’equilibri d’un ecosistema?|What helps keep an ecosystem in balance?', 'protegerlo y no introducir especies|protegir-lo i no introduir espècies|protecting it and not introducing species', ['cazar sin control|caçar sense control|unlimited hunting', 'verter residuos|abocar residus|dumping waste'], 'Hay que respetar sus relaciones.|Cal respectar les seues relacions.|Its relationships must be respected.'),
    M('En un ecosistema, la luz del sol es necesaria sobre todo para…|En un ecosistema, la llum del sol és necessària sobretot per a…|In an ecosystem, sunlight is needed mainly for…', 'que las plantas hagan la fotosíntesis|que les plantes facen la fotosíntesi|plants to photosynthesise', ['que los animales duerman|que els animals dormen|animals to sleep', 'que llueva|que ploga|rain to fall'], 'Las plantas son la base de la cadena.|Les plantes són la base de la cadena.|Plants are the base of the chain.'),
  ]),
  '5P-CM-4': lesson(['Una especie se extingue cuando desaparece para siempre. Causas: destrucción del hábitat, caza y pesca excesivas, contaminación, especies invasoras y cambio climático.|Una espècie s’extingix quan desapareix per sempre. Causes: destrucció de l’hàbitat, caça i pesca excessives, contaminació, espècies invasores i canvi climàtic.|A species becomes extinct when it disappears for ever. Causes: habitat destruction, overhunting and overfishing, pollution, invasive species and climate change.', 'Para evitarlo: espacios protegidos, leyes, cría en cautividad y consumo responsable.|Per a evitar-ho: espais protegits, lleis, cria en captivitat i consum responsable.|To prevent it: protected areas, laws, captive breeding and responsible consumption.'],
    '¿Por qué está en peligro el lince ibérico?|Per què està en perill el linx ibèric?|Why is the Iberian lynx endangered?', ['Su hábitat se ha reducido y faltan conejos, su alimento.|El seu hàbitat s’ha reduït i falten conills, el seu aliment.|Its habitat has shrunk and rabbits, its food, are scarce.', 'Gracias a la protección, su población está aumentando.|Gràcies a la protecció, la seua població està augmentant.|Thanks to protection, its numbers are rising.'], [
    M('¿Qué significa que una especie está extinguida?|Què significa que una espècie està extingida?|What does it mean when a species is extinct?', 'Que ya no queda ningún ejemplar|Que ja no en queda cap exemplar|None are left anywhere', ['Que está dormida|Que està adormida|It is asleep', 'Que vive en el zoo|Que viu en el zoo|It lives in a zoo'], 'Desaparece para siempre.|Desapareix per sempre.|It is gone for ever.'),
    M('¿Cuál es una causa de extinción?|Quina és una causa d’extinció?|Which is a cause of extinction?', 'la destrucción del hábitat|la destrucció de l’hàbitat|habitat destruction', ['plantar árboles|plantar arbres|planting trees', 'crear parques naturales|crear parcs naturals|creating nature reserves'], 'Sin hogar, la especie no sobrevive.|Sense llar, l’espècie no sobreviu.|Without a home, the species cannot survive.'),
    TF('Los dinosaurios se extinguieron hace millones de años.|Els dinosaures es van extingir fa milions d’anys.|Dinosaurs became extinct millions of years ago.', true, 'Hace unos 66 millones de años.|Fa uns 66 milions d’anys.|About 66 million years ago.'),
    M('¿Qué medida protege a las especies?|Quina mesura protegix les espècies?|Which measure protects species?', 'crear espacios naturales protegidos|crear espais naturals protegits|creating protected areas', ['cazar más|caçar més|more hunting', 'contaminar los ríos|contaminar els rius|polluting rivers'], 'Protegen su hábitat.|Protegixen el seu hàbitat.|They protect habitats.'),
    M('¿Qué animal en peligro vive en el Mediterráneo?|Quin animal en perill viu en la Mediterrània?|Which endangered animal lives in the Mediterranean?', 'la tortuga boba|la tortuga babaua|the loggerhead turtle', ['el pingüino emperador|el pingüí emperador|the emperor penguin', 'el canguro|el cangur|the kangaroo'], 'Los plásticos del mar le hacen daño.|Els plàstics de la mar li fan mal.|Sea plastics harm it.'),
    M('¿Cómo puedes ayudar desde casa?|Com pots ajudar des de casa?|How can you help from home?', 'no tirar plásticos y consumir con responsabilidad|no tirar plàstics i consumir amb responsabilitat|avoiding litter and consuming responsibly', ['comprar animales exóticos|comprar animals exòtics|buying exotic pets', 'malgastar agua|malbaratar aigua|wasting water'], 'Los gestos diarios cuentan.|Els gestos diaris compten.|Daily actions count.'),
  ]),
  '5P-CM-5': lesson(['El cuerpo funciona gracias a sus sistemas y aparatos: digestivo (alimentos), respiratorio (aire), circulatorio (sangre), excretor (eliminar desechos), nervioso (control), locomotor (movimiento) y reproductor.|El cos funciona gràcies als seus sistemes i aparells: digestiu (aliments), respiratori (aire), circulatori (sang), excretor (eliminar residus), nerviós (control), locomotor (moviment) i reproductor.|The body works thanks to its systems: digestive (food), respiratory (air), circulatory (blood), excretory (removing waste), nervous (control), locomotor (movement) and reproductive.', 'Todos trabajan juntos para mantener el equilibrio del cuerpo.|Tots treballen junts per a mantindre l’equilibri del cos.|They all work together to keep the body balanced.'],
    '¿Qué aparato lleva el oxígeno a todo el cuerpo?|Quin aparell porta l’oxigen a tot el cos?|Which system carries oxygen round the whole body?', ['El oxígeno entra por los pulmones y viaja en la sangre.|L’oxigen entra pels pulmons i viatja en la sang.|Oxygen enters through the lungs and travels in the blood.', 'El aparato circulatorio.|L’aparell circulatori.|The circulatory system.'], [
    M('¿Qué sistema controla todo el cuerpo?|Quin sistema controla tot el cos?|Which system controls the whole body?', 'el nervioso|el nerviós|the nervous system', ['el digestivo|el digestiu|the digestive system', 'el excretor|l’excretor|the excretory system'], 'Lo forman el cerebro y los nervios.|El formen el cervell i els nervis.|It is the brain and nerves.'),
    M('¿Qué aparato transforma los alimentos en nutrientes?|Quin aparell transforma els aliments en nutrients?|Which system turns food into nutrients?', 'el digestivo|el digestiu|the digestive system', ['el respiratorio|el respiratori|the respiratory system', 'el locomotor|el locomotor|the locomotor system'], 'Boca, estómago, intestinos…|Boca, estómac, intestins…|Mouth, stomach, intestines…'),
    M('¿Qué aparato forman los huesos y los músculos?|Quin aparell formen els ossos i els músculs?|Which system do bones and muscles make up?', 'el locomotor|el locomotor|the locomotor system', ['el circulatorio|el circulatori|the circulatory system', 'el excretor|l’excretor|the excretory system'], 'Sirve para movernos.|Servix per a moure’ns.|It lets us move.'),
    M('¿Qué aparato elimina los desechos de la sangre en forma de orina?|Quin aparell elimina els residus de la sang en forma d’orina?|Which system removes waste from blood as urine?', 'el excretor (urinario)|l’excretor (urinari)|the excretory (urinary) system', ['el digestivo|el digestiu|the digestive system', 'el nervioso|el nerviós|the nervous system'], 'Riñones y vejiga.|Ronyons i bufeta.|Kidneys and bladder.'),
    TF('Al hacer ejercicio, el corazón y la respiración se aceleran.|En fer exercici, el cor i la respiració s’acceleren.|When you exercise, your heart and breathing speed up.', true, 'Los músculos necesitan más oxígeno.|Els músculs necessiten més oxigen.|Muscles need more oxygen.'),
    M('Los sentidos envían información al…|Els sentits envien informació al…|The senses send information to the…', 'cerebro|cervell|brain', ['estómago|estómac|stomach', 'pulmón|pulmó|lung'], 'Por los nervios.|Pels nervis.|Through the nerves.'),
  ]),
  '5P-CM-6': lesson(['Una dieta equilibrada combina hidratos de carbono (energía), proteínas (crecer), grasas buenas, vitaminas y minerales (proteger), fibra y agua.|Una dieta equilibrada combina hidrats de carboni (energia), proteïnes (créixer), greixos bons, vitamines i minerals (protegir), fibra i aigua.|A balanced diet combines carbohydrates (energy), protein (growth), healthy fats, vitamins and minerals (protection), fibre and water.', 'Hábitos de salud: dormir lo suficiente, hacer ejercicio, higiene, revisiones médicas y evitar el tabaco y el alcohol.|Hàbits de salut: dormir prou, fer exercici, higiene, revisions mèdiques i evitar el tabac i l’alcohol.|Healthy habits: enough sleep, exercise, hygiene, check-ups, and avoiding tobacco and alcohol.'],
    '¿Qué nutriente da sobre todo energía?|Quin nutrient dona sobretot energia?|Which nutrient mainly gives energy?', ['Está en el pan, la pasta y el arroz.|Està en el pa, la pasta i l’arròs.|It is in bread, pasta and rice.', 'Los hidratos de carbono.|Els hidrats de carboni.|Carbohydrates.'], [
    M('¿Para qué sirven sobre todo las proteínas?|Per a què servixen sobretot les proteïnes?|What are proteins mainly for?', 'para crecer y reparar el cuerpo|per a créixer i reparar el cos|growth and repair', ['para dar sabor|per a donar sabor|flavour', 'para nada|per a res|nothing'], 'Forman músculos y tejidos.|Formen músculs i teixits.|They build muscles and tissues.'),
    M('¿Qué alimento tiene más fibra?|Quin aliment té més fibra?|Which food has more fibre?', 'las legumbres|els llegums|pulses', ['los refrescos|els refrescos|fizzy drinks', 'el azúcar|el sucre|sugar'], 'La fibra ayuda a la digestión.|La fibra ajuda a la digestió.|Fibre helps digestion.'),
    TF('El tabaco y el alcohol dañan la salud.|El tabac i l’alcohol fan mal a la salut.|Tobacco and alcohol harm health.', true, 'Afectan a pulmones, corazón e hígado.|Afecten els pulmons, el cor i el fetge.|They affect lungs, heart and liver.'),
    M('¿Qué grasa es más saludable?|Quin greix és més saludable?|Which fat is healthier?', 'el aceite de oliva|l’oli d’oliva|olive oil', ['la bollería industrial|la brioixeria industrial|packaged pastries', 'la comida rápida frita|el menjar ràpid fregit|fried fast food'], 'Es típica de la dieta mediterránea.|És típica de la dieta mediterrània.|It is typical of the Mediterranean diet.'),
    M('¿Cuánta agua conviene beber al día?|Quanta aigua convé beure al dia?|How much water should you drink a day?', 'varios vasos a lo largo del día|diversos gots al llarg del dia|several glasses through the day', ['ninguno|cap|none', 'solo refrescos|només refrescos|only fizzy drinks'], 'El cuerpo pierde agua con el sudor y la orina.|El cos perd aigua amb la suor i l’orina.|The body loses water through sweat and urine.'),
    M('¿Qué hábito ayuda a prevenir enfermedades?|Quin hàbit ajuda a previndre malalties?|Which habit helps prevent illness?', 'vacunarse y hacer revisiones|vacunar-se i fer revisions|vaccinations and check-ups', ['no lavarse|no llavar-se|not washing', 'dormir poco|dormir poc|sleeping little'], 'Prevenir es mejor que curar.|Previndre és millor que curar.|Prevention is better than cure.'),
  ]),
  '5P-CM-7': lesson(['Gestionar las emociones es reconocerlas, aceptarlas y elegir cómo actuar. No elegimos lo que sentimos, pero sí lo que hacemos.|Gestionar les emocions és reconéixer-les, acceptar-les i triar com actuar. No triem el que sentim, però sí el que fem.|Managing emotions means recognising them, accepting them and choosing how to act. We cannot choose what we feel, but we can choose what we do.', 'Las relaciones sanas se basan en el respeto, la confianza y el consentimiento: nadie debe obligarte a hacer algo que no quieres.|Les relacions sanes es basen en el respecte, la confiança i el consentiment: ningú t’ha d’obligar a fer una cosa que no vols.|Healthy relationships are built on respect, trust and consent: nobody should make you do something you do not want to.'],
    'Un amigo insiste en que le dejes copiar los deberes y no quieres. ¿Qué haces?|Un amic insistix que li deixes copiar els deures i no vols. Què fas?|A friend keeps asking to copy your homework and you do not want them to. What do you do?', ['Tengo derecho a decir que no.|Tinc dret a dir que no.|I have the right to say no.', 'Le digo que no con calma y le ofrezco explicarle cómo se hace.|Li dic que no amb calma i li oferisc explicar-li com es fa.|I calmly say no and offer to explain how to do it.'], [
    M('Decir lo que piensas con respeto, sin agredir ni callarte, se llama…|Dir el que penses amb respecte, sense agredir ni callar, es diu…|Saying what you think respectfully, without attacking or staying silent, is called…', 'asertividad|assertivitat|assertiveness', ['agresividad|agressivitat|aggression', 'timidez|timidesa|shyness'], 'Es el punto medio.|És el punt mitjà.|It is the middle way.'),
    M('Estás muy enfadado. ¿Qué te ayuda a calmarte?|Estàs molt enfadat. Què t’ajuda a calmar-te?|You are very angry. What helps you calm down?', 'Contar hasta diez y respirar|Comptar fins a deu i respirar|Counting to ten and breathing', ['Gritar a alguien|Cridar algú|Shouting at someone', 'Dar un portazo|Donar una portada|Slamming a door'], 'Así piensas antes de actuar.|Així penses abans d’actuar.|You think before acting.'),
    TF('En una relación sana, las dos personas se respetan.|En una relació sana, les dues persones es respecten.|In a healthy relationship, both people respect each other.', true, 'Respeto y confianza son la base.|Respecte i confiança són la base.|Respect and trust are the foundation.'),
    M('Un compañero se ríe siempre de otro y le deja solo. ¿Qué haces?|Un company sempre es riu d’un altre i el deixa sol. Què fas?|A classmate always laughs at another and leaves them out. What do you do?', 'Apoyar al compañero y avisar a un adulto|Donar suport al company i avisar un adult|Support the classmate and tell an adult', ['Reírte tú también|Riure’t tu també|Laugh too', 'No hacer nada|No fer res|Do nothing'], 'El acoso nunca se debe tolerar.|L’assetjament no s’ha de tolerar mai.|Bullying must never be tolerated.'),
    M('¿Qué emoción sientes cuando algo te da asco?|Quina emoció sents quan una cosa et fa fàstic?|What emotion do you feel when something disgusts you?', 'asco|fàstic|disgust', ['alegría|alegria|joy', 'orgullo|orgull|pride'], 'Nos protege de cosas que pueden ser dañinas.|Ens protegix de coses que poden ser perjudicials.|It protects us from harmful things.'),
    M('¿Qué es la empatía?|Què és l’empatia?|What is empathy?', 'entender cómo se siente otra persona|entendre com se sent una altra persona|understanding how someone else feels', ['pensar solo en mí|pensar només en mi|only thinking about myself', 'ganar siempre|guanyar sempre|always winning'], 'Ponerse en su lugar.|Posar-se en el seu lloc.|Putting yourself in their shoes.'),
  ]),
  '5P-CM-8': lesson(['La masa es la cantidad de materia que tiene un cuerpo (se mide en kg o g). El volumen es el espacio que ocupa (se mide en L, mL o cm³).|La massa és la quantitat de matèria que té un cos (es mesura en kg o g). El volum és l’espai que ocupa (es mesura en L, mL o cm³).|Mass is how much matter an object has (measured in kg or g). Volume is the space it takes up (measured in L, mL or cm³).', 'La densidad relaciona las dos: densidad = masa ÷ volumen. Lo que es menos denso que el agua flota; lo más denso, se hunde.|La densitat relaciona les dues: densitat = massa ÷ volum. El que és menys dens que l’aigua sura; el més dens, s’enfonsa.|Density links the two: density = mass ÷ volume. Things less dense than water float; denser things sink.'],
    '¿Por qué flota un tronco y se hunde una piedra pequeña?|Per què sura un tronc i s’enfonsa una pedra xicoteta?|Why does a log float but a small stone sink?', ['No depende solo del tamaño.|No depén només de la grandària.|It does not just depend on size.', 'La madera es menos densa que el agua; la piedra, más.|La fusta és menys densa que l’aigua; la pedra, més.|Wood is less dense than water; stone is denser.'], [
    Nq('Un objeto tiene 200 g de masa y 100 cm³ de volumen. ¿Cuál es su densidad (g/cm³)?|Un objecte té 200 g de massa i 100 cm³ de volum. Quina és la seua densitat (g/cm³)?|An object has a mass of 200 g and a volume of 100 cm³. What is its density (g/cm³)?', 2, [100, 300, 0.5], 'Densidad = masa ÷ volumen.|Densitat = massa ÷ volum.|Density = mass ÷ volume.'),
    M('Si un objeto es menos denso que el agua, ¿qué le pasa en ella?|Si un objecte és menys dens que l’aigua, què li passa en ella?|If an object is less dense than water, what happens in water?', 'flota|sura|it floats', ['se hunde|s’enfonsa|it sinks', 'se disuelve|es dissol|it dissolves'], 'Lo menos denso queda encima.|El menys dens queda damunt.|Less dense things stay on top.'),
    M('¿Con qué se mide la masa?|Amb què es mesura la massa?|What do you measure mass with?', 'con una balanza|amb una balança|scales', ['con una regla|amb un regle|a ruler', 'con un termómetro|amb un termòmetre|a thermometer'], 'Masa = cuánta materia.|Massa = quanta matèria.|Mass = how much matter.'),
    M('El aceite flota sobre el agua porque es…|L’oli sura sobre l’aigua perquè és…|Oil floats on water because it is…', 'menos denso|menys dens|less dense', ['más denso|més dens|denser', 'más caliente|més calent|hotter'], 'Queda por encima.|Queda per damunt.|It stays on top.'),
    M('Un litro de agua ocupa…|Un litre d’aigua ocupa…|One litre of water takes up…', '1 000 cm³|1 000 cm³|1,000 cm³', ['10 cm³|10 cm³|10 cm³', '1 cm³|1 cm³|1 cm³'], '1 L = 1 dm³ = 1 000 cm³.|1 L = 1 dm³ = 1 000 cm³.|1 L = 1 dm³ = 1,000 cm³.'),
    TF('Un kilo de paja y un kilo de hierro tienen la misma masa.|Un quilo de palla i un quilo de ferro tenen la mateixa massa.|A kilo of straw and a kilo of iron have the same mass.', true, 'Pero la paja ocupa mucho más volumen.|Però la palla ocupa molt més volum.|But the straw takes up much more volume.'),
  ]),
  '5P-CM-9': lesson(['Una fuerza puede cambiar la forma de un objeto (deformarlo) o su movimiento (ponerlo en marcha, frenarlo o cambiar su dirección).|Una força pot canviar la forma d’un objecte (deformar-lo) o el seu moviment (posar-lo en marxa, frenar-lo o canviar-ne la direcció).|A force can change an object’s shape (deform it) or its motion (start it, stop it or change its direction).', 'La gravedad atrae los objetos hacia la Tierra. El rozamiento frena lo que se mueve. La velocidad es la distancia recorrida en un tiempo.|La gravetat atrau els objectes cap a la Terra. El fregament frena el que es mou. La velocitat és la distància recorreguda en un temps.|Gravity pulls objects towards the Earth. Friction slows moving things. Speed is distance travelled in a given time.'],
    'Un coche recorre 120 km en 2 horas. ¿A qué velocidad media va?|Un cotxe recorre 120 km en 2 hores. A quina velocitat mitjana va?|A car travels 120 km in 2 hours. What is its average speed?', ['Velocidad = distancia ÷ tiempo.|Velocitat = distància ÷ temps.|Speed = distance ÷ time.', '120 ÷ 2 = 60 km/h.|120 ÷ 2 = 60 km/h.|120 ÷ 2 = 60 km/h.'], [
    Nq('Una bici recorre 30 km en 2 horas. ¿Cuál es su velocidad media en km/h?|Una bici recorre 30 km en 2 hores. Quina és la seua velocitat mitjana en km/h?|A bike travels 30 km in 2 hours. What is its average speed in km/h?', 15, [60, 32, 28], 'Distancia ÷ tiempo.|Distància ÷ temps.|Distance ÷ time.'),
    M('¿Qué fuerza hace que una pelota caiga al suelo?|Quina força fa que una pilota caiga a terra?|What force makes a ball fall to the ground?', 'la gravedad|la gravetat|gravity', ['el rozamiento|el fregament|friction', 'el magnetismo|el magnetisme|magnetism'], 'La Tierra atrae todo hacia su centro.|La Terra ho atrau tot cap al seu centre.|The Earth pulls everything towards its centre.'),
    M('¿Qué fuerza frena una bici cuando dejas de pedalear?|Quina força frena una bici quan deixes de pedalar?|Which force slows a bike when you stop pedalling?', 'el rozamiento|el fregament|friction', ['la gravedad|la gravetat|gravity', 'el empuje del viento a favor|l’empenta del vent a favor|a tailwind'], 'El suelo y el aire frenan.|El terra i l’aire frenen.|The ground and air slow it down.'),
    M('Aplastar una bola de plastilina es un ejemplo de fuerza que…|Aixafar una bola de plastilina és un exemple de força que…|Squashing a ball of plasticine is an example of a force that…', 'deforma|deforma|changes shape', ['acelera|accelera|speeds up', 'no hace nada|no fa res|does nothing'], 'Cambia la forma del objeto.|Canvia la forma de l’objecte.|It changes the object’s shape.'),
    TF('Un imán atrae objetos de hierro sin tocarlos.|Un imant atrau objectes de ferro sense tocar-los.|A magnet attracts iron objects without touching them.', true, 'Es una fuerza a distancia.|És una força a distància.|It is a non-contact force.'),
    M('Para mover un armario pesado, ¿qué es mejor?|Per a moure un armari pesat, què és millor?|To move a heavy wardrobe, what is best?', 'empujar entre varias personas|empényer entre diverses persones|pushing together with others', ['soplar|bufar|blowing', 'mirarlo|mirar-lo|looking at it'], 'Más fuerza, más fácil moverlo.|Més força, més fàcil moure’l.|More force makes it easier.'),
  ]),
  '5P-CM-10': lesson(['El correo electrónico, los foros y los chats sirven para comunicarse y colaborar. La netiqueta son las normas de buena educación en internet.|El correu electrònic, els fòrums i els xats servixen per a comunicar-se i col·laborar. La netiqueta són les normes de bona educació a internet.|Email, forums and chats are for communicating and working together. Netiquette is the set of good-manners rules online.', 'Netiqueta: saluda y despídete, escribe con respeto, no uses solo mayúsculas, revisa antes de enviar y no reenvíes mensajes de otros sin permiso.|Netiqueta: saluda i acomiada’t, escriu amb respecte, no uses només majúscules, revisa abans d’enviar i no reenvies missatges d’altres sense permís.|Netiquette: greet and sign off, write respectfully, do not use all capitals, check before sending and do not forward others’ messages without permission.'],
    '¿Cómo empiezas un correo a tu profesora?|Com comences un correu a la teua professora?|How do you begin an email to your teacher?', ['Un correo formal empieza con un saludo.|Un correu formal comença amb una salutació.|A formal email starts with a greeting.', '«Hola, Laura:» o «Buenos días:».|«Hola, Laura:» o «Bon dia:».|"Dear Laura," or "Good morning,".'], [
    M('Escribir todo en MAYÚSCULAS en un chat parece que…|Escriure tot en MAJÚSCULES en un xat sembla que…|Writing everything in CAPITALS in a chat looks like you are…', 'estás gritando|estàs cridant|shouting', ['estás contento|estàs content|happy', 'escribes mejor|escrius millor|writing better'], 'Por eso no se hace.|Per això no es fa.|That is why it is avoided.'),
    M('¿Qué hay que poner en el «asunto» de un correo?|Què cal posar en l’«assumpte» d’un correu?|What goes in the "subject" of an email?', 'de qué trata, en pocas palabras|de què tracta, en poques paraules|what it is about, briefly', ['tu contraseña|la teua contrasenya|your password', 'nada nunca|res mai|nothing ever'], 'Ayuda a quien lo recibe.|Ajuda qui el rep.|It helps the person receiving it.'),
    TF('Se puede reenviar un mensaje privado de un amigo sin preguntarle.|Es pot reenviar un missatge privat d’un amic sense preguntar-li.|You can forward a friend’s private message without asking.', false, 'Es suyo: pide permiso.|És seu: demana permís.|It is theirs: ask first.'),
    M('En un foro de clase, alguien opina distinto que tú. ¿Qué haces?|En un fòrum de classe, algú opina diferent que tu. Què fas?|In a class forum, someone disagrees with you. What do you do?', 'Respondo con respeto y argumentos|Responc amb respecte i arguments|Reply respectfully with reasons', ['Le insulto|L’insulte|Insult them', 'Me burlo|Em burle|Make fun of them'], 'Se puede discrepar con educación.|Es pot discrepar amb educació.|You can disagree politely.'),
    M('Antes de enviar un correo importante, ¿qué haces?|Abans d’enviar un correu important, què fas?|Before sending an important email, what do you do?', 'Lo releo para corregir errores|El rellig per a corregir errors|Reread it to fix mistakes', ['Lo envío sin mirar|L’envie sense mirar|Send without checking', 'Borro el saludo|Esborre la salutació|Delete the greeting'], 'Revisar evita malentendidos.|Revisar evita malentesos.|Checking avoids misunderstandings.'),
    M('Recibes un correo de un desconocido con un archivo adjunto. ¿Qué haces?|Reps un correu d’un desconegut amb un fitxer adjunt. Què fas?|You get an email from a stranger with an attachment. What do you do?', 'No lo abro y aviso a un adulto|No l’òbric i avise un adult|Do not open it and tell an adult', ['Abro el archivo|Òbric el fitxer|Open the file', 'Contesto con mis datos|Contesto amb les meues dades|Reply with my details'], 'Puede tener un virus.|Pot tindre un virus.|It may contain a virus.'),
  ]),
  '5P-CM-11': lesson(['Una contraseña segura es larga y mezcla mayúsculas, minúsculas, números y símbolos. No uses tu nombre ni tu fecha de nacimiento, y no la compartas.|Una contrasenya segura és llarga i mescla majúscules, minúscules, nombres i símbols. No uses el teu nom ni la teua data de naixement, i no la compartisques.|A strong password is long and mixes capitals, lower case, numbers and symbols. Do not use your name or birthday, and do not share it.', 'El spam es correo basura. El phishing es un engaño para robar datos: un mensaje que parece de un banco o una tienda y te pide claves o que pulses un enlace.|L’spam és correu brossa. El phishing és un engany per a robar dades: un missatge que sembla d’un banc o una botiga i et demana claus o que premes un enllaç.|Spam is junk mail. Phishing is a trick to steal information: a message that looks like it is from a bank or shop and asks for passwords or for you to click a link.'],
    'Te llega: «Tu cuenta será bloqueada. Escribe aquí tu contraseña». ¿Qué es?|Et arriba: «El teu compte serà bloquejat. Escriu ací la teua contrasenya». Què és?|You receive: "Your account will be blocked. Type your password here". What is it?', ['Nadie de confianza te pide la contraseña por mensaje.|Ningú de confiança et demana la contrasenya per missatge.|No trustworthy service asks for your password by message.', 'Es phishing: no contesto, lo borro y aviso a un adulto.|És phishing: no contesto, l’esborre i avise un adult.|It is phishing: I do not reply, I delete it and tell an adult.'], [
    M('¿Qué contraseña es más segura?|Quina contrasenya és més segura?|Which password is strongest?', 'Mar!Nube47Sol|Mar!Núvol47Sol|Sea!Cloud47Sun', ['ana2015|ana2015|ana2015', '123456|123456|123456'], 'Larga y con mezcla de caracteres.|Llarga i amb mescla de caràcters.|Long, with mixed characters.'),
    M('El correo basura que llega sin pedirlo se llama…|El correu brossa que arriba sense demanar-lo es diu…|Junk email you did not ask for is called…', 'spam|spam|spam', ['netiqueta|netiqueta|netiquette', 'contraseña|contrasenya|a password'], 'Suele ser publicidad.|Sol ser publicitat.|It is usually advertising.'),
    TF('Es seguro usar la misma contraseña para todo.|És segur usar la mateixa contrasenya per a tot.|It is safe to use the same password for everything.', false, 'Si la descubren, entran en todo.|Si la descobrixen, entren en tot.|If someone finds it, they get into everything.'),
    M('Un desconocido en un juego en línea te pide una foto. ¿Qué haces?|Un desconegut en un joc en línia et demana una foto. Què fas?|A stranger in an online game asks for a photo. What do you do?', 'No se la envío, lo bloqueo y aviso a un adulto|No li l’envie, el bloquege i avise un adult|Do not send it, block them and tell an adult', ['Se la envío|Li l’envie|Send it', 'Le doy mi dirección|Li done la meua adreça|Give my address'], 'Nunca compartas imágenes con desconocidos.|Mai compartisques imatges amb desconeguts.|Never share pictures with strangers.'),
    M('Un enlace raro dice: «¡Descarga el juego sin pagar!». ¿Qué haces?|Un enllaç estrany diu: «Descarrega el joc sense pagar!». Què fas?|A strange link says: "Download the game for nothing!". What do you do?', 'No lo pulso: puede tener virus|No el prem: pot tindre virus|Do not click: it may contain a virus', ['Lo pulso rápido|El prem ràpid|Click it quickly', 'Lo envío a todos|L’envie a tots|Send it to everyone'], 'Las descargas dudosas son peligrosas.|Les descàrregues dubtoses són perilloses.|Dodgy downloads are dangerous.'),
    M('¿Qué es el phishing?|Què és el phishing?|What is phishing?', 'un engaño para robar datos|un engany per a robar dades|a trick to steal personal data', ['un tipo de pez|un tipus de peix|a kind of fish', 'un juego|un joc|a game'], 'Te «pescan» los datos.|Et «pesquen» les dades.|They "fish" for your data.'),
  ]),
  '5P-CM-12': lesson(['Para buscar bien: usa palabras clave, buscadores seguros, filtra los resultados y comprueba la información en varias fuentes fiables.|Per a buscar bé: usa paraules clau, cercadors segurs, filtra els resultats i comprova la informació en diverses fonts fiables.|To search well: use key words and safe search engines, filter the results and check information in several reliable sources.', 'Para guardar la información, organízala en carpetas con nombres claros, en el ordenador o en la nube.|Per a guardar la informació, organitza-la en carpetes amb noms clars, en l’ordinador o en el núvol.|To save information, organise it in clearly named folders on the computer or in the cloud.'],
    'Has encontrado datos para un trabajo sobre volcanes. ¿Cómo los guardas?|Has trobat dades per a un treball sobre volcans. Com les guardes?|You have found information for a project on volcanoes. How do you save it?', ['Con orden se encuentra todo después.|Amb ordre es troba tot després.|With good organisation you can find it later.', 'En una carpeta llamada «Ciencias – Volcanes».|En una carpeta anomenada «Ciències – Volcans».|In a folder named "Science – Volcanoes".'], [
    M('¿Qué fuente es más fiable?|Quina font és més fiable?|Which source is more reliable?', 'una enciclopedia o una web oficial|una enciclopèdia o una web oficial|an encyclopaedia or official website', ['un comentario anónimo|un comentari anònim|an anonymous comment', 'un mensaje en cadena|un missatge en cadena|a chain message'], 'Mira quién la firma.|Mira qui la signa.|Check who wrote it.'),
    M('¿Qué es «la nube»?|Què és «el núvol»?|What is "the cloud"?', 'guardar archivos en servidores de internet|guardar fitxers en servidors d’internet|storing files on internet servers', ['el tiempo atmosférico|el temps atmosfèric|the weather', 'un programa de dibujo|un programa de dibuix|a drawing program'], 'Puedes abrirlos desde otros aparatos.|Pots obrir-los des d’altres aparells.|You can open them from other devices.'),
    M('Para no perder un trabajo, ¿qué es buena idea?|Per a no perdre un treball, què és bona idea?|To avoid losing your work, what is a good idea?', 'hacer una copia de seguridad|fer una còpia de seguretat|making a backup', ['no guardarlo|no guardar-lo|not saving it', 'borrarlo|esborrar-lo|deleting it'], 'Guarda en dos sitios.|Guarda en dos llocs.|Save it in two places.'),
    TF('Conviene poner nombres claros a los archivos.|Convé posar noms clars als fitxers.|It is a good idea to give files clear names.', true, 'Así los encuentras rápido.|Així els trobes ràpid.|Then you can find them quickly.'),
    M('Has copiado un texto de una web para tu trabajo. ¿Qué debes hacer?|Has copiat un text d’una web per al teu treball. Què has de fer?|You copied text from a website for your project. What should you do?', 'Decir de qué web es y ponerlo entre comillas|Dir de quina web és i posar-lo entre cometes|Say which website it is from and put it in quotation marks', ['Decir que lo has escrito tú|Dir que l’has escrit tu|Say you wrote it', 'Cambiar dos palabras|Canviar dues paraules|Change two words'], 'Respeta el trabajo de otros.|Respecta el treball d’altres.|Respect other people’s work.'),
    M('Buscas «tiburón blanco tamaño». ¿Qué son esas palabras?|Busques «tauró blanc grandària». Què són eixes paraules?|You search "great white shark size". What are those words?', 'palabras clave|paraules clau|key words', ['una contraseña|una contrasenya|a password', 'una dirección|una adreça|an address'], 'Las más importantes de tu pregunta.|Les més importants de la teua pregunta.|The most important words in your question.'),
  ]),
  '5P-CM-13': lesson(['En la programación por bloques usamos secuencias (órdenes en orden), bucles (repetir) y condicionales («si ocurre esto, haz aquello»). También variables, que guardan datos como la puntuación.|En la programació per blocs usem seqüències (ordres en ordre), bucles (repetir) i condicionals («si passa açò, fes allò»). També variables, que guarden dades com la puntuació.|In block programming we use sequences (instructions in order), loops (repeat) and conditionals ("if this happens, do that"). Also variables, which store data such as the score.'],
    '¿Cómo haces que un personaje diga «¡Bien!» al tocar una estrella?|Com fas que un personatge diga «Bé!» en tocar una estrela?|How do you make a character say "Well done!" when it touches a star?', ['Es una condición: si toca la estrella…|És una condició: si toca l’estrela…|It is a condition: if it touches the star…', '«Si tocando estrella, entonces decir ¡Bien!».|«Si tocant estrela, aleshores dir Bé!».|"If touching star, then say Well done!".'], [
    M('¿Qué bloque usas para que algo pase solo si se cumple una condición?|Quin bloc uses perquè una cosa passe només si es complix una condició?|Which block makes something happen only if a condition is true?', 'si… entonces|si… aleshores|if… then', ['repetir|repetir|repeat', 'esperar|esperar|wait'], 'Es un condicional.|És un condicional.|It is a conditional.'),
    M('Para contar los puntos de un juego, ¿qué usas?|Per a comptar els punts d’un joc, què uses?|To keep the score in a game, what do you use?', 'una variable|una variable|a variable', ['un bucle infinito|un bucle infinit|an infinite loop', 'un disfraz|una disfressa|a costume'], 'Guarda un número que cambia.|Guarda un nombre que canvia.|It stores a number that changes.'),
    Nq('La variable «puntos» vale 0 y se suma 5 tres veces. ¿Cuánto vale al final?|La variable «punts» val 0 i se suma 5 tres vegades. Quant val al final?|The variable "points" is 0 and 5 is added three times. What is it at the end?', 15, [5, 8, 53], '0 + 5 + 5 + 5.|0 + 5 + 5 + 5.|0 + 5 + 5 + 5.'),
    TF('Un bucle repite las órdenes que tiene dentro.|Un bucle repetix les ordres que té dins.|A loop repeats the instructions inside it.', true, 'Así no las escribes muchas veces.|Així no les escrius moltes vegades.|So you do not have to write them many times.'),
    M('¿Qué es una secuencia?|Què és una seqüència?|What is a sequence?', 'órdenes una detrás de otra|ordres una darrere de l’altra|instructions one after another', ['una orden que se repite sin fin|una ordre que es repetix sense fi|an endlessly repeated instruction', 'un dibujo|un dibuix|a drawing'], 'El orden importa.|L’ordre importa.|Order matters.'),
    M('«Repetir 4 veces: avanzar 50 y girar 90°». ¿Qué dibuja?|«Repetir 4 vegades: avançar 50 i girar 90°». Què dibuixa?|"Repeat 4 times: move 50, turn 90°". What does it draw?', 'un cuadrado|un quadrat|a square', ['un triángulo|un triangle|a triangle', 'un círculo|un cercle|a circle'], '4 lados iguales y 4 ángulos rectos.|4 costats iguals i 4 angles rectes.|4 equal sides and 4 right angles.'),
  ]),
  '5P-CM-14': lesson(['Ante un problema técnico, sigue un método: describe qué pasa, comprueba lo más sencillo (conexión, batería, volumen), reinicia, busca ayuda en el manual o pide ayuda a un adulto.|Davant d’un problema tècnic, seguix un mètode: descriu què passa, comprova el més senzill (connexió, bateria, volum), reinicia, busca ajuda en el manual o demana ajuda a un adult.|For a technical problem, follow a method: describe what is happening, check the simple things (connection, battery, volume), restart, look in the manual or ask an adult.'],
    'La impresora no imprime. ¿Qué compruebas primero?|La impressora no imprimix. Què comproves primer?|The printer will not print. What do you check first?', ['Lo más sencillo primero.|El més senzill primer.|Simplest first.', 'Si está encendida, conectada y tiene papel.|Si està encesa, connectada i té paper.|Whether it is on, connected and has paper.'], [
    M('El vídeo va a saltos. ¿Qué puede pasar?|El vídeo va a salts. Què pot passar?|The video keeps stopping. What could be wrong?', 'La conexión a internet es lenta|La connexió a internet és lenta|The internet connection is slow', ['La pantalla está sucia|La pantalla està bruta|The screen is dirty', 'El ratón es viejo|El ratolí és vell|The mouse is old'], 'Los vídeos necesitan buena conexión.|Els vídeos necessiten bona connexió.|Videos need a good connection.'),
    M('El teclado no escribe. ¿Qué miras?|El teclat no escriu. Què mires?|The keyboard will not type. What do you check?', 'si está conectado o tiene pilas|si està connectat o té piles|whether it is connected or has batteries', ['el color de las teclas|el color de les tecles|the colour of the keys', 'la hora|l’hora|the time'], 'Revisa la conexión.|Revisa la connexió.|Check the connection.'),
    TF('Reiniciar un aparato soluciona muchos problemas.|Reiniciar un aparell soluciona molts problemes.|Restarting a device fixes many problems.', true, 'Vuelve a empezar limpio.|Torna a començar net.|It starts afresh.'),
    M('¿Dónde puedes buscar cómo funciona un aparato?|On pots buscar com funciona un aparell?|Where can you find out how a device works?', 'en su manual de instrucciones|en el seu manual d’instruccions|in its instruction manual', ['en un libro de cuentos|en un llibre de contes|in a storybook', 'en ningún sitio|en cap lloc|nowhere'], 'El fabricante lo explica.|El fabricant ho explica.|The manufacturer explains it.'),
    M('La batería del portátil se gasta muy rápido. ¿Qué puede ayudar?|La bateria del portàtil es gasta molt ràpid. Què pot ajudar?|The laptop battery runs down fast. What can help?', 'bajar el brillo y cerrar programas|baixar la brillantor i tancar programes|turning down brightness and closing programs', ['abrir muchos programas|obrir molts programes|opening lots of programs', 'darle golpes|donar-li colps|hitting it'], 'Gastas menos energía.|Gastes menys energia.|It uses less power.'),
    M('Has probado todo y sigue sin funcionar. ¿Qué haces?|Has provat tot i continua sense funcionar. Què fas?|You have tried everything and it still does not work. What do you do?', 'Pedir ayuda a un adulto o a un técnico|Demanar ajuda a un adult o a un tècnic|Ask an adult or a technician', ['Desmontarlo con un cuchillo|Desmuntar-lo amb un ganivet|Take it apart with a knife', 'Tirarlo|Tirar-lo|Throw it away'], 'Sin riesgos: pide ayuda.|Sense riscos: demana ajuda.|No risks: ask for help.'),
  ]),
  '5P-CM-15': lesson(['El Universo es todo lo que existe: miles de millones de galaxias, cada una con miles de millones de estrellas. Nuestra galaxia es la Vía Láctea.|L’univers és tot el que existix: milers de milions de galàxies, cadascuna amb milers de milions d’estreles. La nostra galàxia és la Via Làctia.|The Universe is everything that exists: billions of galaxies, each with billions of stars. Our galaxy is the Milky Way.', 'Las estrellas tienen luz propia; los planetas, no: reflejan la luz de su estrella. Las distancias son enormes y se miden en años luz.|Les estreles tenen llum pròpia; els planetes, no: reflectixen la llum de la seua estrela. Les distàncies són enormes i es mesuren en anys llum.|Stars give off their own light; planets do not: they reflect their star’s light. Distances are huge and are measured in light years.'],
    '¿Cómo se llama nuestra galaxia?|Com es diu la nostra galàxia?|What is our galaxy called?', ['Se ve como una franja blanca en noches oscuras.|Es veu com una franja blanca en nits fosques.|It looks like a white band on dark nights.', 'La Vía Láctea.|La Via Làctia.|The Milky Way.'], [
    M('¿Qué es una galaxia?|Què és una galàxia?|What is a galaxy?', 'un enorme grupo de estrellas|un enorme grup d’estreles|a huge group of stars', ['un planeta|un planeta|a planet', 'una nube de lluvia|un núvol de pluja|a rain cloud'], 'Contiene miles de millones de estrellas.|Conté milers de milions d’estreles.|It contains billions of stars.'),
    M('¿Qué astro tiene luz propia?|Quin astre té llum pròpia?|Which object gives off its own light?', 'una estrella|una estrela|a star', ['la Luna|la Lluna|the Moon', 'un planeta|un planeta|a planet'], 'Las estrellas brillan; los planetas reflejan.|Les estreles brillen; els planetes reflectixen.|Stars shine; planets reflect.'),
    M('¿Qué mide un año luz?|Què mesura un any llum?|What does a light year measure?', 'una distancia|una distància|a distance', ['un tiempo|un temps|a time', 'una masa|una massa|a mass'], 'Lo que recorre la luz en un año.|El que recorre la llum en un any.|How far light travels in a year.'),
    TF('El Sol es la estrella más cercana a la Tierra.|El Sol és l’estrela més pròxima a la Terra.|The Sun is the nearest star to Earth.', true, 'Las demás están mucho más lejos.|Les altres estan molt més lluny.|The others are much further away.'),
    M('¿Con qué instrumento se observan estrellas lejanas?|Amb quin instrument s’observen estreles llunyanes?|What instrument do we use to observe distant stars?', 'el telescopio|el telescopi|a telescope', ['el microscopio|el microscopi|a microscope', 'el termómetro|el termòmetre|a thermometer'], 'Tele = lejos.|Tele = lluny.|Tele = far.'),
    M('Un grupo de estrellas que forma una figura en el cielo es…|Un grup d’estreles que forma una figura en el cel és…|A group of stars that makes a pattern in the sky is…', 'una constelación|una constel·lació|a constellation', ['un cometa|un cometa|a comet', 'un satélite|un satèl·lit|a satellite'], 'Como la Osa Mayor.|Com l’Óssa Major.|Like the Plough.'),
  ]),
  '5P-CM-16': lesson(['El Sistema Solar tiene planetas rocosos (Mercurio, Venus, Tierra, Marte), más cerca del Sol, y gigantes gaseosos (Júpiter, Saturno, Urano, Neptuno), más lejos. Entre Marte y Júpiter está el cinturón de asteroides.|El sistema solar té planetes rocosos (Mercuri, Venus, Terra, Mart), més prop del Sol, i gegants gasosos (Júpiter, Saturn, Urà, Neptú), més lluny. Entre Mart i Júpiter hi ha el cinturó d’asteroides.|The Solar System has rocky planets (Mercury, Venus, Earth, Mars) nearer the Sun and gas giants (Jupiter, Saturn, Uranus, Neptune) further away. Between Mars and Jupiter is the asteroid belt.', 'La Tierra es el único planeta conocido con vida: tiene agua líquida y una atmósfera con oxígeno.|La Terra és l’únic planeta conegut amb vida: té aigua líquida i una atmosfera amb oxigen.|Earth is the only known planet with life: it has liquid water and an atmosphere with oxygen.'],
    '¿Marte es un planeta rocoso o gaseoso?|Mart és un planeta rocós o gasós?|Is Mars rocky or gaseous?', ['Está entre los cuatro más cercanos al Sol.|Està entre els quatre més pròxims al Sol.|It is one of the four nearest the Sun.', 'Es rocoso.|És rocós.|It is rocky.'], [
    M('¿Qué planeta es un gigante gaseoso?|Quin planeta és un gegant gasós?|Which planet is a gas giant?', 'Júpiter|Júpiter|Jupiter', ['Marte|Mart|Mars', 'Mercurio|Mercuri|Mercury'], 'Es el más grande.|És el més gran.|It is the largest.'),
    M('¿Dónde está el cinturón de asteroides?|On està el cinturó d’asteroides?|Where is the asteroid belt?', 'entre Marte y Júpiter|entre Mart i Júpiter|between Mars and Jupiter', ['entre la Tierra y la Luna|entre la Terra i la Lluna|between the Earth and the Moon', 'detrás de Neptuno|darrere de Neptú|beyond Neptune'], 'Separa los rocosos de los gaseosos.|Separa els rocosos dels gasosos.|It separates rocky and gas planets.'),
    M('¿Por qué hay vida en la Tierra?|Per què hi ha vida en la Terra?|Why is there life on Earth?', 'Tiene agua líquida y atmósfera con oxígeno|Té aigua líquida i atmosfera amb oxigen|It has liquid water and an atmosphere with oxygen', ['Porque es el planeta más grande|Perquè és el planeta més gran|Because it is the biggest planet', 'Porque está más lejos del Sol|Perquè està més lluny del Sol|Because it is furthest from the Sun'], 'Distancia justa al Sol.|Distància justa al Sol.|It is just the right distance from the Sun.'),
    M('¿Cuál es el planeta más caliente?|Quin és el planeta més calent?|Which planet is hottest?', 'Venus|Venus|Venus', ['Neptuno|Neptú|Neptune', 'Marte|Mart|Mars'], 'Su atmósfera atrapa el calor.|La seua atmosfera atrapa la calor.|Its atmosphere traps heat.'),
    TF('Los cometas son bolas de hielo y polvo con cola.|Els cometes són boles de gel i pols amb cua.|Comets are balls of ice and dust with a tail.', true, 'La cola aparece al acercarse al Sol.|La cua apareix quan s’acosten al Sol.|The tail appears as they near the Sun.'),
    Nq('¿Cuántos planetas rocosos hay en el Sistema Solar?|Quants planetes rocosos hi ha en el sistema solar?|How many rocky planets are in the Solar System?', 4, [2, 8, 5], 'Mercurio, Venus, Tierra y Marte.|Mercuri, Venus, Terra i Mart.|Mercury, Venus, Earth and Mars.'),
  ]),
  '5P-CM-17': lesson(['Representamos el territorio con mapas físicos (relieve, ríos), políticos (países, comunidades) y temáticos (climas, población). La escala dice cuánto se ha reducido la realidad.|Representem el territori amb mapes físics (relleu, rius), polítics (països, comunitats) i temàtics (climes, població). L’escala diu quant s’ha reduït la realitat.|We show places with physical maps (landforms, rivers), political maps (countries, regions) and thematic maps (climates, population). The scale shows how much reality has been reduced.', 'Las coordenadas (latitud y longitud) localizan cualquier punto de la Tierra.|Les coordenades (latitud i longitud) localitzen qualsevol punt de la Terra.|Coordinates (latitude and longitude) locate any point on Earth.'],
    'Quieres ver dónde están las montañas y los ríos de España. ¿Qué mapa usas?|Vols veure on estan les muntanyes i els rius d’Espanya. Quin mapa uses?|You want to see Spain’s mountains and rivers. Which map do you use?', ['Las montañas y los ríos son el relieve.|Les muntanyes i els rius són el relleu.|Mountains and rivers are physical features.', 'Un mapa físico.|Un mapa físic.|A physical map.'], [
    M('Un mapa que muestra países y fronteras es…|Un mapa que mostra països i fronteres és…|A map showing countries and borders is…', 'político|polític|political', ['físico|físic|physical', 'del tiempo|del temps|a weather map'], 'Muestra la organización política.|Mostra l’organització política.|It shows how land is organised politically.'),
    M('En un mapa a escala 1:100 000, 1 cm son…|En un mapa a escala 1:100 000, 1 cm són…|On a 1:100,000 map, 1 cm is…', '1 km|1 km|1 km', ['100 m|100 m|100 m', '10 km|10 km|10 km'], '100 000 cm = 1 000 m = 1 km.|100 000 cm = 1 000 m = 1 km.|100,000 cm = 1,000 m = 1 km.'),
    M('¿Qué indican la latitud y la longitud?|Què indiquen la latitud i la longitud?|What do latitude and longitude show?', 'la posición de un lugar en la Tierra|la posició d’un lloc en la Terra|a place’s position on Earth', ['la temperatura|la temperatura|the temperature', 'la población|la població|the population'], 'Son las coordenadas geográficas.|Són les coordenades geogràfiques.|They are geographical coordinates.'),
    M('En un mapa físico, el color marrón oscuro indica…|En un mapa físic, el color marró fosc indica…|On a physical map, dark brown shows…', 'zonas de mucha altitud|zones de molta altitud|high ground', ['el mar|la mar|the sea', 'ciudades|ciutats|cities'], 'Los tonos marrones son montañas.|Els tons marrons són muntanyes.|Brown shades are mountains.'),
    TF('Un mapa del clima es un mapa temático.|Un mapa del clima és un mapa temàtic.|A climate map is a thematic map.', true, 'Trata un tema concreto.|Tracta un tema concret.|It covers a specific topic.'),
    M('El ecuador divide la Tierra en…|L’equador dividix la Terra en…|The equator divides the Earth into…', 'hemisferio norte y sur|hemisferi nord i sud|northern and southern hemispheres', ['este y oeste|est i oest|east and west', 'día y noche|dia i nit|day and night'], 'Es una línea imaginaria horizontal.|És una línia imaginària horitzontal.|It is an imaginary horizontal line.'),
  ]),
  '5P-CM-18': lesson(['Un experimento sirve para comprobar una hipótesis (una posible respuesta). Se controlan las variables: solo cambiamos una y medimos lo que pasa.|Un experiment servix per a comprovar una hipòtesi (una possible resposta). Es controlen les variables: només en canviem una i mesurem el que passa.|An experiment tests a hypothesis (a possible answer). We control the variables: we change only one and measure what happens.', 'Después comunicamos los resultados con tablas, gráficos y conclusiones, para que otros puedan comprobarlos.|Després comuniquem els resultats amb taules, gràfics i conclusions, perquè altres puguen comprovar-los.|Then we share the results with tables, graphs and conclusions so that others can check them.'],
    'Hipótesis: «Las plantas crecen más con más luz». ¿Qué variable cambias?|Hipòtesi: «Les plantes creixen més amb més llum». Quina variable canvies?|Hypothesis: "Plants grow more with more light". Which variable do you change?', ['Solo cambia lo que quieres comprobar.|Només canvia el que vols comprovar.|Only change what you want to test.', 'La cantidad de luz; el agua, la tierra y la maceta, iguales.|La quantitat de llum; l’aigua, la terra i el test, iguals.|The amount of light; water, soil and pot stay the same.'], [
    M('¿Qué es una hipótesis?|Què és una hipòtesi?|What is a hypothesis?', 'una posible respuesta que se puede comprobar|una possible resposta que es pot comprovar|a possible answer that can be tested', ['el resultado final|el resultat final|the final result', 'un material|un material|a material'], 'Se comprueba con un experimento.|Es comprova amb un experiment.|You test it with an experiment.'),
    M('¿Por qué se repite un experimento varias veces?|Per què es repetix un experiment diverses vegades?|Why repeat an experiment several times?', 'para que los resultados sean fiables|perquè els resultats siguen fiables|so the results are reliable', ['para gastar material|per a gastar material|to use up materials', 'porque sí|perquè sí|for no reason'], 'Un solo dato puede ser casualidad.|Una sola dada pot ser casualitat.|One result could be chance.'),
    M('¿Qué forma de comunicar resultados es más clara?|Quina manera de comunicar resultats és més clara?|Which is the clearest way to share results?', 'una tabla y un gráfico|una taula i un gràfic|a table and a graph', ['un dibujo sin datos|un dibuix sense dades|a drawing with no data', 'no decirlos|no dir-los|not saying them'], 'Los datos ordenados se entienden mejor.|Les dades ordenades s’entenen millor.|Organised data is easier to understand.'),
    TF('Si el resultado no confirma la hipótesis, el experimento ha fallado.|Si el resultat no confirma la hipòtesi, l’experiment ha fallat.|If the result does not support the hypothesis, the experiment has failed.', false, 'También se aprende: la hipótesis era falsa.|També s’aprén: la hipòtesi era falsa.|You still learn: the hypothesis was wrong.'),
    M('Las científicas y los científicos comparten sus resultados para…|Les científiques i els científics compartixen els seus resultats per a…|Scientists share their results so that…', 'que otros puedan comprobarlos|que altres puguen comprovar-los|others can check them', ['presumir|presumir|they can show off', 'esconderlos|amagar-los|they can hide them'], 'La ciencia avanza entre muchas personas.|La ciència avança entre moltes persones.|Science moves forward through many people.'),
    M('En la conclusión, ¿qué escribes?|En la conclusió, què escrius?|What do you write in the conclusion?', 'si se cumple la hipótesis y qué has aprendido|si es complix la hipòtesi i què has aprés|whether the hypothesis held and what you learnt', ['la lista de materiales|la llista de materials|the list of materials', 'tu nombre solamente|el teu nom només|only your name'], 'Es el resumen final.|És el resum final.|It is the final summary.'),
  ]),
};
export default P;
